import unicodedata


def slugify(s):
    s = unicodedata.normalize('NFKD', s.lower())
    s = ''.join(ch for ch in s if not unicodedata.combining(ch))
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        elif not out or out[-1] != '-':
            out.append('-')
    return ''.join(out).strip('-')

import unicodedata


def slugify(s):
    s = unicodedata.normalize('NFKD', s).lower()
    out = []
    for ch in s:
        if unicodedata.combining(ch):
            continue
        if ch.isalnum():
            out.append(ch)
        elif ch.isspace() or ch in '-_':
            if not out or out[-1] != '-':
                out.append('-')
    return ''.join(out).strip('-')

import unicodedata

def slugify(s):
    s = unicodedata.normalize('NFD', s).lower()
    out = []
    for ch in s:
        if unicodedata.combining(ch):
            continue
        if ch.isascii() and ch.isalnum():
            out.append(ch)
        elif out and out[-1] != '-':
            out.append('-')
    return ''.join(out).strip('-')
